setTimeout(() => console.log("B"), 0);               // 5. task → B
Promise.resolve().then(() => console.log("C"));      // 3. microtask → C
queueMicrotask(() => console.log("D"));              // 4. microtask → D
console.log("E");                                    // 2. sync → E

// Output: A, E, C, D, B
